CREATE TABLE IF NOT EXISTS course_catalog_import (source_row INT PRIMARY KEY, category VARCHAR(255), faculty VARCHAR(255), major VARCHAR(255), course_code VARCHAR(30) NOT NULL, section_code VARCHAR(20) NOT NULL, course_name VARCHAR(255) NOT NULL, credits VARCHAR(30), hours VARCHAR(30), instructor_name VARCHAR(255), schedule_raw TEXT) CHARACTER SET utf8mb4;
START TRANSACTION;
COMMIT;
